<?php /** @var list<array<string,mixed>> $templates */ /** @var list<string> $placeholders */ /** @var bool $canManage */ ?>
<p class="eyebrow"><a href="/agreements">Agreements</a></p><h1>Agreement templates</h1>
<p class="muted">Placeholders filled in when an agreement is made: <?php foreach ($placeholders as $p) : ?><code>{{<?= e($p) ?>}}</code> <?php endforeach; ?>. Editing a template creates a new version; agreements already created keep the text they were made with.</p>
<?php foreach ($templates as $t) : ?><div class="panel"><h2><?= e($t['name']) ?> <span class="muted">v<?= (int) $t['current_version'] ?><?= $t['status'] === 'retired' ? ' · retired' : '' ?></span></h2>
    <?php if ($canManage) : ?><form method="post" action="/agreement-templates/<?= e($t['public_id']) ?>" class="form-grid"><?= csrf_field() ?><div class="field"><label>Name</label><input name="name" required maxlength="160" value="<?= e($t['name']) ?>"></div><div class="field"><label>Text</label><textarea name="body" rows="10" maxlength="60000"><?= e($t['body']) ?></textarea></div><div class="form-actions"><button class="btn btn-primary btn-sm" type="submit">Save new version</button></div></form>
        <form method="post" action="/agreement-templates/<?= e($t['public_id']) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="retire"><button class="btn btn-ghost btn-sm" type="submit"><?= $t['status'] === 'active' ? 'Retire' : 'Reactivate' ?></button></form>
    <?php else : ?><div class="prewrap"><?= e($t['body']) ?></div><?php endif; ?></div><?php endforeach; ?>
<?php if ($canManage) : ?><div class="panel"><h2>New template</h2><form method="post" action="/agreement-templates" class="form-grid"><?= csrf_field() ?><div class="field"><label for="nn">Name</label><input id="nn" name="name" required maxlength="160" value="<?= e(old('name')) ?>"></div><div class="field"><label for="nb">Text</label><textarea id="nb" name="body" rows="10" maxlength="60000"><?= e(old('body')) ?></textarea></div><div class="form-actions"><button class="btn btn-primary" type="submit">Create template</button></div></form></div><?php endif; ?>
